        switch model.backend {
        case .tinyIntent, .mock, .remote:
            return verificationStatus != .missingFile
                && verificationStatus != .hashMismatch
                && verificationStatus != .unreadable
                && verificationStatus != .unsupported
        case .gguf, .coreML:
